#include <metal_simdgroup_matrix>
inline float qmv_qdot16(const device uint32_t* w, thread const float* xt, float s, float b, float sum) {
  float accum = 0.0f;
  for (uint i = 0; i < 4u; ++i) {
    uint word = w[i >> 1];
    uint ws = (i & 1u) ? (word >> 16) : (word & 0xFFFFu);
    accum += (xt[4u * i] * float(ws & 0x000Fu) + xt[4u * i + 1u] * float(ws & 0x00F0u) + xt[4u * i + 2u] * float(ws & 0x0F00u) + xt[4u * i + 3u] * float(ws & 0xF000u));
  }
  return s * accum + sum * b;
}
inline void mlx_deq8(uint q, bfloat16_t scale, bfloat16_t bias, threadgroup bfloat16_t* dst, uint ld) {
  bfloat16_t sc0 = scale;
  bfloat16_t sc1 = scale / static_cast<bfloat16_t>(16.0f);
  for (uint i = 0; i < 4u; ++i) {
    uint byte = (q >> (8u * i)) & 0xFFu;
    dst[(2u * i) * ld] = sc0 * static_cast<bfloat16_t>(byte & 0x0Fu) + bias;
    dst[(2u * i + 1u) * ld] = sc1 * static_cast<bfloat16_t>(byte & 0xF0u) + bias;
  }
}
inline uint4 load_a8(const device ushort* p, uint base, uint k, uint st2, bool vec, bool valid) {
  if (!valid) {
    return uint4(0u);
  }
  if (vec) {
    return *((const device uint4*)(p + base + k));
  }
  uint w[4];
  for (uint j = 0; j < 4u; ++j) {
    uint lo = (uint)p[base + (k + 2u * j) * st2];
    uint hi = (uint)p[base + (k + 2u * j + 1u) * st2];
    w[j] = lo | (hi << 16);
  }
  return uint4(w[0], w[1], w[2], w[3]);
}
